/* ===================== NOMBRES ET CALCULS · chapter nc =====================
   Trainers of the chapter «Числа и вычисления» (cycle 4, DNB 2027 — first of all Partie 1 «Automatismes»).
   nc.frac-addsub lives in 00-base.js. Every top-level name of this file starts with nc. */

/* ---------- helpers ---------- */
/* integer n · 10^-k → decimal in input syntax without trailing zeros: ncD(-47, 1) → '-4.7' */
const ncD = (n, k) => decT(n, k || 0);
/* decimal in input syntax → plain text: '-4.7' → '−4,7', '311200000' → '311 200 000' (no float formatting, so 4,57e-7 never appears) */
function ncTxt(s) {
  s = String(s); const neg = s[0] === '-'; if (neg) s = s.slice(1);
  let [i, d] = s.split('.'); if (i.length >= 5) i = i.replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
  return (neg ? '−' : '') + i + (d ? ',' + d : '');
}
/* integer n · 10^-k → plain text: ncN(-47, 1) → '−4,7' */
const ncN = (n, k) => ncTxt(ncD(n, k));
/* a number inside a formula, in brackets when negative: (-4.7) */
const ncP = s => (String(s)[0] === '-' ? '(' + s + ')' : String(s));
/* TeX of a fraction, in brackets when negative */
const ncTP = f => (f.n < 0 ? '\\left(' + tF(f) + '\\right)' : tF(f));
/* Russian plural: ncPl(5, 'знак', 'знака', 'знаков') → 'знаков' */
function ncPl(n, one, few, many) { n = Math.abs(n) % 100; const m = n % 10; return n > 10 && n < 20 ? many : m === 1 ? one : m >= 2 && m <= 4 ? few : many; }
/* «4 равные части», «5 равных частей», «3 равных промежутка» … */
const ncParts2 = n => n + ' ' + ncPl(n, 'равную часть', 'равные части', 'равных частей');
const ncGaps = n => n + ' ' + ncPl(n, 'равный промежуток', 'равных промежутка', 'равных промежутков');
const ncTimes = n => n + ' ' + ncPl(n, 'раз', 'раза', 'раз');
/* multiple choice: the right option first, the others are typical mistakes; an option repeated by chance is dropped */
function ncMQ(r, opts) {
  const seen = new Set(), out = [];
  opts.forEach(o => { const k = (typeof o === 'string' ? o : o.fr).replace(/\s+/g, ''); if (!seen.has(k)) { seen.add(k); out.push(o); } });
  return MQ(r, out, 0);
}
/* why a + b is what it is; a, b are integers meaning a·10^-k */
function ncSumWhy(a, b, k, plain) {
  const A = Math.abs(a), B = Math.abs(b), s = a + b;
  if ((a < 0) === (b < 0)) return a < 0
    ? 'Оба числа отрицательные' + (plain ? '' : ' — как два долга: они складываются') + '. Складываем расстояния до нуля: ' + ncN(A, k) + ' + ' + ncN(B, k) + ' = ' + ncN(A + B, k) + ', знак «минус» остаётся.'
    : 'Оба числа положительные — обычное сложение: ' + ncN(A, k) + ' + ' + ncN(B, k) + ' = ' + ncN(A + B, k) + '.';
  return 'Знаки разные' + (plain ? ': числа частично гасят друг друга' : ' — как долг и деньги в кармане: они частично гасят друг друга') + '. Из большего расстояния до нуля вычитаем меньшее: ' + ncN(Math.max(A, B), k) + ' − ' + ncN(Math.min(A, B), k) + ' = ' + ncN(Math.abs(A - B), k) + '. Знак берём у числа, которое дальше от нуля (' + ncN(A > B ? a : b, k) + '), поэтому результат ' + (s < 0 ? 'отрицательный.' : 'положительный.');
}
/* how to multiply two decimals |a| = an·10^-ak, |b| = bn·10^-bk (text) */
function ncMulWhy(an, ak, bn, bk) {
  const pn = an * bn, pk = ak + bk, a = ncN(an, ak), b = ncN(bn, bk), full = ncTxt(dec(pn, pk)), p = ncN(pn, pk);
  if (!pk) return a + ' × ' + b + ' = ' + p + '.';
  return 'Перемножаем числа без запятых: ' + an + ' × ' + bn + ' = ' + pn + '. Во множителях вместе ' + pk + ' ' + ncPl(pk, 'знак', 'знака', 'знаков') + ' после запятой' + (ak === 1 && bk === 1 ? ' (десятые × десятые = сотые)' : '') + ', значит, и в произведении ' + pk + ': ' + a + ' × ' + b + ' = ' + full + (full !== p ? ' = ' + p : '') + '.';
}

/* ===================== RELATIVE NUMBERS: + and − ===================== */
topic({ id: 'nc.relatifs-addsub', ch: 'nc', lvl: 1, calc: false, variants: 5,
  ru: 'Сложение и вычитание относительных чисел', fr: 'Additionner et soustraire des nombres relatifs',
  hints: [
    'Представь числовую прямую: прибавить положительное число — шагнуть вправо, прибавить отрицательное — шагнуть влево. Или думай о деньгах: $-5$ — долг 5 €, а $3$ — 3 € в кармане.',
    'Знаки одинаковые — расстояния до нуля складываются, знак тот же: $-3-4=-7$ (долг плюс долг). Знаки разные — из большего расстояния вычитаем меньшее, а знак берём у числа, которое дальше от нуля: $-4.7+3.5=-1.2$.',
    'Вычесть число — то же, что прибавить противоположное («l\'opposé»): $5-(-2)=5+2=7$. Вычитание отменяет сложение: списать долг 2 € — всё равно что получить 2 €.'],
  gen(r, vi) {
    const dn = () => (r() < 0.3 ? 10 * r.ri(1, 15) : r.ri(11, 99));    /* a positive number in tenths: 1,1 … 9,9 or a whole number */
    if (vi === 0) {   /* the sum of two relative numbers (Métropole 2026 Q2: −4,7 + 3,5) */
      let a, b; do { a = dn() * r.sgn(); b = dn() * r.sgn(); } while (Math.abs(a) === Math.abs(b) || (a > 0 && b > 0));
      const m = ncD(a, 1) + '+' + ncP(ncD(b, 1)), s = a + b, sol = [];
      if (b < 0) sol.push('Прибавить отрицательное число — шагнуть по прямой влево, то есть уменьшить на его расстояние до нуля.');
      sol.push(ncSumWhy(a, b, 1), ['', m + '=' + ncD(s, 1)]);
      return { q: L('Calculer la somme suivante.', 'Вычисли сумму.'), m, ans: N(ncD(s, 1)), sol };
    }
    if (vi === 1) {   /* subtracting a relative number */
      let a, b; do { a = dn() * r.sgn(); b = r() < 0.65 ? -dn() : dn(); } while (Math.abs(a) === Math.abs(b) || (b > 0 && a > b));
      const m = ncD(a, 1) + '-' + ncP(ncD(b, 1)), s = a - b;
      return { q: L('Calculer la différence suivante.', 'Вычисли разность.'), m, ans: N(ncD(s, 1)), sol: [
        ['Вычесть число — значит прибавить противоположное ему («l\'opposé»). Противоположное к ' + ncN(b, 1) + ' — это ' + ncN(-b, 1) + '.', m + '=' + ncD(a, 1) + '+' + ncP(ncD(-b, 1))],
        b < 0 ? 'Почему так: вычитание отменяет сложение. Списать долг ' + ncN(-b, 1) + ' € — всё равно что получить ' + ncN(-b, 1) + ' €.' : 'Прибавить ' + ncN(-b, 1) + ' — значит шагнуть по прямой влево на ' + ncN(b, 1) + '.',
        ncSumWhy(a, -b, 1),
        ['', m + '=' + ncD(s, 1)]] };
    }
    if (vi === 2) {   /* several terms */
      let t; do { t = []; const n = r.ri(4, 5); for (let i = 0; i < n; i++) t.push(r.nz(-15, 15)); } while (t.filter(x => x > 0).length < 2 || t.filter(x => x < 0).length < 2 || !t.reduce((s, x) => s + x, 0));
      const pos = t.filter(x => x > 0), neg = t.filter(x => x < 0), P = pos.reduce((s, x) => s + x, 0), Q = neg.reduce((s, x) => s + x, 0), s = P + Q;
      return { q: L('Calculer $A$.', 'Вычисли $A$.'), m: 'A=' + S(t.map(String)), ans: N(s), sol: [
        'Слагаемые можно переставлять: от перестановки слагаемых сумма не меняется. Соберём отдельно положительные числа («доходы») и отрицательные («долги»).',
        ['Положительные:', S(pos.map(String)) + '=' + P],
        ['Отрицательные — долги складываются:', S(neg.map(String)) + '=' + Q],
        [ncSumWhy(P, Q, 0), S(String(P), String(Q)) + '=' + s]] };
    }
    if (vi === 3) {   /* multiple choice: the usual sign mistakes */
      let a, b; do { a = dn(); b = dn(); } while (a === b);
      const plus = r() < 0.6; if (!plus && a > b) [a, b] = [b, a];
      const m = plus ? ncD(-a, 1) + '+' + ncD(b, 1) : ncD(a, 1) + '-' + ncD(b, 1), s = plus ? b - a : a - b;
      const x = plus ? -a : a, y = plus ? b : -b;   /* the expression is x + y */
      return { q: L('Parmi les propositions suivantes, laquelle est égale à $' + m + '$ ?', 'Какое из чисел равно $' + m + '$?'),
        ans: ncMQ(r, [s, -s, a + b, -(a + b)].map(v => '$' + ncD(v, 1) + '$')), sol: [
          plus ? ncSumWhy(x, y, 1) : 'Вычесть ' + ncN(b, 1) + ' — значит прибавить ' + ncN(-b, 1) + '. ' + ncSumWhy(x, y, 1),
          ['', m + '=' + ncD(s, 1)],
          'Ответы ' + ncN(a + b, 1) + ' и ' + ncN(-(a + b), 1) + ' получаются, если сложить расстояния до нуля. Но знаки разные — числа частично гасят друг друга, поэтому расстояния вычитают.',
          'Ответ ' + ncN(-s, 1) + ' — потерян знак: дальше от нуля число ' + ncN(Math.abs(x) > Math.abs(y) ? x : y, 1) + ', его знак и получает результат.'] };
    }
    /* vi === 4: relative numbers in context */
    const kind = r.ri(0, 3);
    if (kind === 0) {   /* the temperature rises from below zero */
      const t1 = -r.ri(2, 14), t2 = r.ri(1, 12), h1 = r.ri(5, 8), h2 = r.ri(13, 16);
      return { q: L('Un matin d\'hiver, à ' + h1 + ' h, la température était de ' + nf(t1) + ' °C. À ' + h2 + ' h, elle était de ' + t2 + ' °C. De combien de degrés la température a-t-elle augmenté ?',
        'Зимним утром в ' + h1 + ' ч температура была ' + nf(t1) + ' °C. В ' + h2 + ' ч она стала ' + t2 + ' °C. На сколько градусов повысилась температура?'),
        ans: N(t2 - t1, { unit: '°C' }), sol: [
          'Изменение — это «стало» минус «было». Так считают всегда, даже когда «было» — отрицательное число.',
          ['Вычесть отрицательное — прибавить противоположное:', t2 + '-(' + t1 + ')=' + t2 + '+' + (-t1) + '=' + (t2 - t1), '°C'],
          'Проверка по термометру: от ' + nf(t1) + ' до 0 — ' + (-t1) + ' ' + ncPl(-t1, 'градус', 'градуса', 'градусов') + ', от 0 до ' + t2 + ' — ещё ' + t2 + ', всего ' + (t2 - t1) + '.'] };
    }
    if (kind === 1) {   /* the temperature falls below zero */
      const t1 = r.ri(-4, 9); const d = t1 + r.ri(2, 9); const t2 = t1 - d;
      return { q: L('Le soir, le thermomètre indique ' + nf(t1) + ' °C. Pendant la nuit, la température baisse de ' + d + ' °C. Quelle température indique le thermomètre le matin ?',
        'Вечером термометр показывает ' + nf(t1) + ' °C. За ночь температура понижается на ' + d + ' °C. Что показывает термометр утром?'),
        ans: N(t2, { unit: '°C' }), sol: [
          'Понижение на ' + d + ' ' + ncPl(d, 'градус', 'градуса', 'градусов') + ' — значит, вычитаем ' + d + ', то есть шагаем по шкале вниз.',
          ncSumWhy(t1, -d, 0, true),
          ['', t1 + '-' + d + '=' + t2, '°C']] };
    }
    if (kind === 2) {   /* a bank account */
      const fem = r() < 0.5, who = r.pick(fem ? PRENOMS_F : PRENOMS_M), dep = r() < 0.5; let s0, x;
      do { s0 = 5 * r.ri(-16, 12); x = 5 * r.ri(4, 30); } while (!s0 || (dep ? s0 >= 0 || s0 + x === 0 : s0 - x >= 0));
      const s1 = dep ? s0 + x : s0 - x;
      return { q: L('Le compte bancaire de ' + who + ' affiche un solde de ' + eur(s0) + '. ' + (dep ? (fem ? 'Elle' : 'Il') + ' dépose ' + eur(x) + ' sur ce compte.' : (fem ? 'Elle' : 'Il') + ' paie un achat de ' + eur(x) + ' avec sa carte.') + ' Quel est le nouveau solde du compte ?',
        'На банковском счёте у ' + who + ' баланс ' + eur(s0) + '. ' + (dep ? (fem ? 'Она кладёт' : 'Он кладёт') + ' на счёт ' + eur(x) + '.' : (fem ? 'Она оплачивает' : 'Он оплачивает') + ' картой покупку на ' + eur(x) + '.') + ' Каким стал баланс счёта?'),
        ans: N(s1, { unit: '€' }), sol: [
          dep ? 'Пополнение счёта — прибавляем. Отрицательный баланс — это долг банку: деньги сначала идут на его погашение.' : 'Покупка — вычитаем: деньги уходят со счёта, и баланс может стать отрицательным (долг банку).',
          ncSumWhy(s0, dep ? x : -x, 0),
          ['', s0 + (dep ? '+' : '-') + x + '=' + s1, '€']] };
    }
    const z0 = -r.ri(6, 30), up = r() < 0.5, x = up ? r.ri(2, -z0 - 1) : r.ri(2, 15), z1 = up ? z0 + x : z0 - x;   /* a diver */
    return { q: L('Un plongeur se trouve à ' + (-z0) + ' m sous la surface de la mer : son altitude est de ' + nf(z0) + ' m. Il ' + (up ? 'remonte' : 'descend') + ' de ' + x + ' m. Quelle est sa nouvelle altitude ?',
      'Дайвер находится на глубине ' + (-z0) + ' м под поверхностью моря: его высота над уровнем моря ' + nf(z0) + ' м. Он ' + (up ? 'поднимается' : 'опускается') + ' на ' + x + ' м. Какой стала его высота?'),
      ans: N(z1, { unit: 'm' }), sol: [
        up ? 'Подъём — прибавляем: высота растёт, то есть становится ближе к нулю (к поверхности).' : 'Спуск — вычитаем: высота уменьшается, дайвер уходит дальше от поверхности.',
        ncSumWhy(z0, up ? x : -x, 0, true),
        ['', z0 + (up ? '+' : '-') + x + '=' + z1, 'm']] };
  } });

/* ===================== RELATIVE NUMBERS: × and ÷ ===================== */
topic({ id: 'nc.relatifs-muldiv', ch: 'nc', lvl: 1, calc: false, variants: 5,
  ru: 'Умножение и деление относительных чисел', fr: 'Multiplier et diviser des nombres relatifs',
  hints: [
    'Сначала перемножь (или раздели) числа без знаков, а знак результата определи отдельно.',
    'Правило знаков: одинаковые знаки — «плюс», разные — «минус». Если множителей много, посчитай минусы: чётное число — результат положительный, нечётное — отрицательный.',
    'Почему минус на минус — плюс: умножить на $-1$ — значит заменить число противоположным. $(-2)*(-3)$ — противоположное к $(-2)*3=-6$, то есть $6$. Или по закономерности: $2*(-3)=-6$, $1*(-3)=-3$, $0*(-3)=0$ — каждый раз прибавляется 3, значит, $(-1)*(-3)=3$.'],
  gen(r, vi) {
    if (vi === 0) {   /* product of two */
      let a, b; do { a = r.nz(-12, 12); b = r.nz(-12, 12); } while ((a > 0 && b > 0) || Math.abs(a) < 2 || Math.abs(b) < 2);
      const m = ncP(a) + '*' + ncP(b), p = a * b;
      return { q: L('Calculer le produit suivant.', 'Вычисли произведение.'), m, ans: N(p), sol: [
        'Без знаков: ' + Math.abs(a) + ' × ' + Math.abs(b) + ' = ' + Math.abs(p) + '.',
        [(a < 0) === (b < 0) ? 'Знаки одинаковые (минус на минус) — произведение положительное.' : 'Знаки разные — произведение отрицательное.', m + '=' + p]] };
    }
    if (vi === 1) {   /* quotient */
      let b, q; do { b = r.nz(-9, 9); q = r.nz(-12, 12); } while ((b > 0 && q > 0) || Math.abs(b) < 2 || Math.abs(q) < 2);
      const a = b * q, m = ncP(a) + '÷' + ncP(b);
      return { q: L('Calculer le quotient suivant.', 'Вычисли частное.'), m, ans: N(q), sol: [
        'Деление проверяется умножением: ищем число, которое при умножении на ' + nf(b) + ' даёт ' + nf(a) + '.',
        'Без знаков: ' + Math.abs(a) + ' ÷ ' + Math.abs(b) + ' = ' + Math.abs(q) + '. Знаки ' + ((a < 0) === (b < 0) ? 'одинаковые — частное положительное' : 'разные — частное отрицательное') + ': правило знаков то же, что для умножения, ведь деление — обратное действие.',
        ['Проверка умножением:', ncP(q) + '*' + ncP(b) + '=' + a]] };
    }
    if (vi === 2) {   /* several factors: count the minus signs */
      let f, p; do { f = []; const n = r.ri(3, 4); for (let i = 0; i < n; i++) f.push(r.nz(-6, 6)); p = f.reduce((s, x) => s * x, 1); } while (f.filter(x => x < 0).length < 2 || Math.abs(p) > 300 || f.filter(x => Math.abs(x) === 1).length > 1);
      const k = f.filter(x => x < 0).length, m = f.map(ncP).join('*');
      return { q: L('Calculer le produit suivant.', 'Вычисли произведение.'), m, ans: N(p), sol: [
        'Считаем отрицательные множители: их ' + k + '. ' + (k % 2 ? 'Минусы гасятся парами (минус на минус — плюс), и один остаётся без пары — произведение отрицательное.' : 'Минусы гасятся парами (минус на минус — плюс), лишнего не остаётся — произведение положительное.'),
        ['Без знаков:', f.map(x => Math.abs(x)).join('*') + '=' + Math.abs(p)],
        ['', m + '=' + p]] };
    }
    if (vi === 3) {   /* the sign of a product without computing it */
      const n = r.ri(3, 8), k = r.ri(1, n);
      return { q: L('On multiplie ' + n + ' nombres relatifs non nuls ; ' + (k === 1 ? 'un seul d\'entre eux est négatif' : k === n ? 'ils sont tous négatifs' : k + ' d\'entre eux sont négatifs') + '. Le produit est :',
        'Перемножают ' + n + ' ненулевых относительных ' + ncPl(n, 'число', 'числа', 'чисел') + '; ' + (k === 1 ? 'отрицательное среди них только одно' : k === n ? 'все они отрицательные' : 'отрицательных среди них ' + k) + '. Произведение:'),
        ans: MQF([L('positif', 'положительное'), L('négatif', 'отрицательное'), L('nul', 'равно нулю'), L('on ne peut pas savoir', 'нельзя определить')], k % 2 ? 1 : 0), sol: [
          'Положительные множители на знак не влияют, а каждая пара отрицательных даёт «плюс» (минус на минус — плюс).',
          k + ' ' + ncPl(k, 'минус', 'минуса', 'минусов') + ': ' + (k % 2 ? 'после разбиения на пары один минус остаётся — произведение отрицательное.' : 'все разбиваются на пары — произведение положительное.'),
          'Нулю произведение равно, только если один из множителей равен нулю, а здесь все множители ненулевые. Значит, знак известен наверняка, хотя самих чисел мы не знаем.'] };
    }
    /* vi === 4: decimals */
    const P = [[5, 1, 8, 0], [25, 1, 4, 0], [12, 1, 3, 0], [3, 1, 2, 1], [15, 1, 6, 0], [25, 2, 12, 0], [4, 1, 5, 0], [25, 1, 4, 1], [5, 1, 5, 1], [2, 1, 7, 0], [15, 1, 4, 0], [75, 2, 4, 0], [6, 1, 5, 0], [12, 1, 5, 0], [8, 1, 3, 0], [35, 1, 2, 0]];
    const [an, ak, bn, bk] = r.pick(P); let sa, sb; do { sa = r.sgn(); sb = r.sgn(); } while (sa > 0 && sb > 0);
    const A = ncD(sa * an, ak), B = ncD(sb * bn, bk), pn = sa * sb * an * bn, pk = ak + bk;
    const m = r() < 0.5 ? ncP(B) + '*' + ncP(A) : ncP(A) + '*' + ncP(B);
    return { q: L('Calculer le produit suivant.', 'Вычисли произведение.'), m, ans: N(ncD(pn, pk)), sol: [
      'Сначала без знаков. ' + ncMulWhy(an, ak, bn, bk),
      [sa === sb ? 'Знаки одинаковые — произведение положительное.' : 'Знаки разные — произведение отрицательное.', m + '=' + ncD(pn, pk)]] };
  } });

/* ===================== ORDER OF OPERATIONS ===================== */
topic({ id: 'nc.priorites', ch: 'nc', lvl: 1, calc: false, variants: 5,
  ru: 'Порядок действий', fr: 'Les priorités opératoires',
  hints: [
    'Сначала то, что в скобках. Потом умножение и деление. И только потом сложение и вычитание.',
    'Почему умножение раньше сложения: $5+3*4$ — это 5 и ещё три раза по 4, то есть $5+12$. Умножение — сокращённая запись сложения одинаковых слагаемых, поэтому его результат нужен раньше.',
    'Действия одного уровня (только сложение и вычитание или только умножение и деление) выполняют слева направо: $20-5+3=15+3=18$. Черта дроби работает как скобки: числитель и знаменатель считают отдельно, потом делят.'],
  gen(r, vi) {
    const q = L('Calculer en respectant les priorités opératoires.', 'Вычисли, соблюдая порядок действий.');
    if (vi === 0) {   /* × or ÷ before + and − */
      const t = r.ri(0, 3), a = r.ri(2, 30), b = r.ri(2, 9), c = r.ri(2, 9), d = r.ri(2, 9);
      if (t === 0) return { q, m: a + '+' + b + '*' + c, ans: N(a + b * c), sol: [
        ['Сначала умножение: ' + b + ' × ' + c + ' — это ' + b + ' раз по ' + c + ', это число нужно знать до сложения.', b + '*' + c + '=' + (b * c)],
        ['Потом сложение:', a + '+' + (b * c) + '=' + (a + b * c)],
        'Если считать подряд слева направо, вышло бы ' + ((a + b) * c) + ' — это ответ на другой пример, $(' + a + '+' + b + ')*' + c + '$.'] };
      if (t === 1) { const v = a - b * c; return { q, m: a + '-' + b + '*' + c, ans: N(v), sol: [
        ['Сначала умножение (оно выполняется раньше вычитания):', b + '*' + c + '=' + (b * c)],
        ['Потом вычитание' + (v < 0 ? ' — вычитаем больше, чем было, поэтому результат отрицательный:' : ':'), a + '-' + (b * c) + '=' + v]] }; }
      if (t === 2) { const x = r.ri(2, 12); return { q, m: x + '*' + b + '+' + c + '*' + d, ans: N(x * b + c * d), sol: [
        ['Оба умножения выполняем раньше сложения:', x + '*' + b + '=' + (x * b) + ';' + c + '*' + d + '=' + (c * d)],
        ['Потом складываем результаты:', (x * b) + '+' + (c * d) + '=' + (x * b + c * d)]] }; }
      const v = a - b; return { q, m: a + '-' + (b * c) + '÷' + c, ans: N(v), sol: [
        ['Сначала деление (оно выполняется раньше вычитания):', (b * c) + '÷' + c + '=' + b],
        ['Потом вычитание:', a + '-' + b + '=' + v]] };
    }
    if (vi === 1) {   /* brackets first */
      const t = r.ri(0, 4), a = r.ri(2, 12), [b, c] = r.distinct(2, 2, 9);
      if (t === 0) return { q, m: a + '*(' + b + '+' + c + ')', ans: N(a * (b + c)), sol: [
        ['Сначала скобки:', b + '+' + c + '=' + (b + c)], ['Потом умножение:', a + '*' + (b + c) + '=' + (a * (b + c))],
        'Без скобок было бы $' + a + '*' + b + '+' + c + '=' + (a * b + c) + '$: скобки как раз и показывают, что сначала нужно сложить.'] };
      if (t === 1) { const x = b + r.ri(1, 9); return { q, m: '(' + x + '-' + b + ')*' + c, ans: N((x - b) * c), sol: [
        ['Сначала скобки:', x + '-' + b + '=' + (x - b)], ['Потом умножение:', (x - b) + '*' + c + '=' + ((x - b) * c)]] }; }
      if (t === 2) { const x = r.ri(10, 30), y = c + r.ri(2, 9); return { q, m: x + '-(' + y + '-' + c + ')', ans: N(x - (y - c)), sol: [
        ['Сначала скобки:', y + '-' + c + '=' + (y - c)], ['Потом вычитание:', x + '-' + (y - c) + '=' + (x - (y - c))],
        'Частая ошибка — вычесть и ' + y + ', и ' + c + '. Но из ' + x + ' вычитают не ' + y + ', а разность ' + (y - c) + ' — она на ' + c + ' меньше, чем ' + y + '. Поэтому и ответ на ' + c + ' больше, чем ' + x + ' − ' + y + ': $' + x + '-(' + y + '-' + c + ')=' + x + '-' + y + '+' + c + '$.'] }; }
      if (t === 3) { const x = r.ri(20, 60), y = c + r.ri(1, 5); const v = x - b * (y - c); return { q, m: x + '-' + b + '*(' + y + '-' + c + ')', ans: N(v), sol: [
        ['Сначала скобки:', y + '-' + c + '=' + (y - c)], ['Потом умножение:', b + '*' + (y - c) + '=' + (b * (y - c))], ['В конце вычитание:', x + '-' + (b * (y - c)) + '=' + v]] }; }
      const k = r.ri(2, 9), s = c * k, x = r.ri(1, s - 1); return { q, m: '(' + x + '+' + (s - x) + ')÷' + c, ans: N(k), sol: [
        ['Сначала скобки:', x + '+' + (s - x) + '=' + s], ['Потом деление:', s + '÷' + c + '=' + k]] };
    }
    if (vi === 2) {   /* the fraction bar groups like brackets */
      const t = r.ri(0, 2), c = r.ri(2, 9), k = r.ri(2, 12);
      if (t === 0) { const den = c, d = r.ri(1, 9), num = k * den, a = r.ri(1, num - 1); return { q, m: '(' + a + '+' + (num - a) + ')/(' + (den + d) + '-' + d + ')', ans: N(k), sol: [
        'Черта дроби — это деление всего числителя на весь знаменатель, поэтому сначала считаем их отдельно, как будто они в скобках.',
        ['Числитель и знаменатель:', a + '+' + (num - a) + '=' + num + ';' + (den + d) + '-' + d + '=' + den],
        ['Делим:', num + '÷' + den + '=' + k]] }; }
      if (t === 1) { let a, b, s1, s2; do { a = r.ri(2, 9); b = r.ri(2, 12); s1 = r.ri(1, 9); s2 = r.ri(1, 9); } while ((a * b) % (s1 + s2) || a * b === s1 + s2); return { q, m: '(' + a + '*' + b + ')/(' + s1 + '+' + s2 + ')', ans: N(a * b / (s1 + s2)), sol: [
        'Черта дроби работает как скобки: сначала считаем числитель и знаменатель, потом делим.',
        ['Числитель и знаменатель:', a + '*' + b + '=' + (a * b) + ';' + s1 + '+' + s2 + '=' + (s1 + s2)],
        ['Делим:', (a * b) + '÷' + (s1 + s2) + '=' + (a * b / (s1 + s2))]] }; }
      const a = r.ri(2, 20), b = c * k; return { q, m: a + '+' + b + '/' + c, ans: N(a + k), sol: [
        'Черта дроби стоит только под числом ' + b + ': делится только оно, а ' + a + ' прибавляется потом. Деление выполняется раньше сложения.',
        ['', b + '/' + c + '=' + k], ['', a + '+' + k + '=' + (a + k)]] };
    }
    if (vi === 3) {   /* multiple choice (sujet de référence 2027 n°2, Q1: 2,5 − 5,5 + 3 × 4) */
      let a, b, c, d, v; do { a = r.ri(11, 59); b = a + r.ri(5, 45); c = r.ri(2, 6); d = r.ri(2, 9); if (a % 10 === 0 || b % 10 === 0) continue;
        v = [a - b + 10 * c * d, (a - b + 10 * c) * d, a - b - 10 * c * d, b - a + 10 * c * d]; } while (!v || new Set(v).size < 4);
      const m = ncD(a, 1) + '-' + ncD(b, 1) + '+' + c + '*' + d;
      return { q: L('Le nombre $A=' + m + '$ est égal à :', 'Число $A=' + m + '$ равно:'), ans: ncMQ(r, v.map(x => '$' + ncD(x, 1) + '$')), sol: [
        ['Сначала умножение:', c + '*' + d + '=' + (c * d)],
        ['Потом сложение и вычитание по порядку, слева направо:', ncD(a, 1) + '-' + ncD(b, 1) + '=' + ncD(a - b, 1) + ';' + ncD(a - b, 1) + '+' + (c * d) + '=' + ncD(v[0], 1)],
        'Ответ ' + ncN(v[1], 1) + ' — если считать всё подряд слева направо и умножить в самом конце.',
        'Ответ ' + ncN(v[2], 1) + ' — если решить, что «минус» относится ко всему, что стоит после него.',
        'Ответ ' + ncN(v[3], 1) + ' — ошибка в знаке: ' + ncN(a, 1) + ' − ' + ncN(b, 1) + ' = ' + ncN(a - b, 1) + ' (вычитаем больше, чем было), а не ' + ncN(b - a, 1) + '.'] };
    }
    /* vi === 4: from words to an expression */
    const [b, c] = r.distinct(2, 2, 9), a = r.distinct(1, 2, 20, [b, c])[0], t = r.ri(0, 3);
    const T = [
      { fr: 'la somme de ' + a + ' et du produit de ' + b + ' par ' + c, ru: 'сумма числа ' + a + ' и произведения ' + b + ' на ' + c,
        ok: a + '+' + b + '*' + c, bad: ['(' + a + '+' + b + ')*' + c, a + '*' + b + '+' + c, a + '+' + b + '+' + c],
        why: 'Первое слово — «la somme»: в конце складываем. Слагаемые — число ' + a + ' и произведение ' + b + ' × ' + c + '. Скобки не нужны: умножение и так выполняется раньше сложения.' },
      { fr: 'le produit de la somme de ' + a + ' et ' + b + ' par ' + c, ru: 'произведение суммы чисел ' + a + ' и ' + b + ' на ' + c,
        ok: '(' + a + '+' + b + ')*' + c, bad: [a + '+' + b + '*' + c, a + '*' + b + '+' + c, a + '*(' + b + '+' + c + ')'],
        why: 'Первое слово — «le produit»: в конце умножаем. Первый множитель — сумма ' + a + ' + ' + b + ', второй — ' + c + '. Сумму надо посчитать раньше умножения, поэтому она в скобках.' },
      { fr: 'la différence entre ' + a + ' et le produit de ' + b + ' par ' + c, ru: 'разность числа ' + a + ' и произведения ' + b + ' на ' + c,
        ok: a + '-' + b + '*' + c, bad: ['(' + a + '-' + b + ')*' + c, b + '*' + c + '-' + a, a + '*' + b + '-' + c],
        why: 'Первое слово — «la différence»: в конце вычитаем. Из числа ' + a + ' вычитаем произведение ' + b + ' × ' + c + ' (порядок важен: сначала то, из чего вычитают). Скобки не нужны: умножение выполняется раньше.' },
      { fr: 'le quotient de la somme de ' + a + ' et ' + b + ' par ' + c, ru: 'частное от деления суммы чисел ' + a + ' и ' + b + ' на ' + c,
        ok: '(' + a + '+' + b + ')÷' + c, bad: [a + '+' + b + '÷' + c, a + '÷(' + b + '+' + c + ')', '(' + a + '+' + b + ')*' + c],
        why: 'Первое слово — «le quotient»: в конце делим. Делимое — сумма ' + a + ' + ' + b + ', делитель — ' + c + '. Сумму нужно посчитать до деления, поэтому она в скобках.' }][t];
    return { q: L('Quelle expression correspond à la phrase « ' + T.fr + ' » ?', 'Какое выражение соответствует фразе «' + T.ru + '»?'),
      ans: ncMQ(r, [T.ok].concat(T.bad).map(x => '$' + x + '$')), sol: [
        'Выражение называют по последнему действию. ' + T.why,
        ['Ответ:', T.ok]] };
  } });

/* ===================== DECIMALS WITHOUT A CALCULATOR ===================== */
topic({ id: 'nc.decimaux', ch: 'nc', lvl: 1, calc: false, variants: 5,
  ru: 'Десятичные дроби без калькулятора', fr: 'Calculer avec des nombres décimaux',
  hints: [
    'Каждая цифра стоит в своём разряде: единицы, десятые («dixièmes»), сотые («centièmes»), тысячные («millièmes»). Складывают и вычитают цифры одного разряда — поэтому запятую пишут под запятой.',
    'Умножить на 10 — каждая десятая становится единицей, каждая единица — десятком: цифры сдвигаются на разряд выше, запятая — на знак вправо. Умножить на 0,1 — взять десятую часть, то есть разделить на 10.',
    'При умножении десятичных: десятые × десятые = сотые ($0.3*0.2=0.06$). Поэтому перемножь числа без запятых и отсчитай справа столько знаков, сколько их во множителях вместе.'],
  gen(r, vi) {
    const q = L('Calculer :', 'Вычисли:');
    if (vi === 0) {   /* × and ÷ by 10, 100, 1000, 0,1, 0,01 */
      const ops = [['*10', 1], ['*100', 2], ['*1000', 3], ['÷10', -1], ['÷100', -2], ['÷1000', -3], ['*0.1', -1], ['*0.01', -2], ['÷0.1', 1], ['÷0.01', 2]];
      const [op, sh] = r.pick(ops), k = r.ri(0, 3); let n; do n = r.ri(2, k ? 9999 : 999); while (n % 10 === 0 || String(n).length < 2 && k > 1);
      const e = sh - k, res = e >= 0 ? String(n * Math.pow(10, e)) : ncD(n, -e), x = ncD(n, k), m = x + op;
      const why = {
        '*10': 'Умножить на 10 — каждая цифра переходит на один разряд выше (десятые становятся единицами, единицы — десятками), поэтому запятая сдвигается на 1 знак вправо.',
        '*100': 'Умножить на 100 — каждая цифра переходит на два разряда выше, поэтому запятая сдвигается на 2 знака вправо; недостающие разряды заполняем нулями.',
        '*1000': 'Умножить на 1000 — каждая цифра переходит на три разряда выше, поэтому запятая сдвигается на 3 знака вправо; недостающие разряды заполняем нулями.',
        '÷10': 'Разделить на 10 — каждая цифра переходит на один разряд ниже (единицы становятся десятыми), поэтому запятая сдвигается на 1 знак влево.',
        '÷100': 'Разделить на 100 — каждая цифра переходит на два разряда ниже, поэтому запятая сдвигается на 2 знака влево; если цифр не хватает, слева пишем нули.',
        '÷1000': 'Разделить на 1000 — каждая цифра переходит на три разряда ниже, поэтому запятая сдвигается на 3 знака влево; если цифр не хватает, слева пишем нули.',
        '*0.1': 'Умножить на 0,1 — взять одну десятую числа, то есть разделить на 10: запятая сдвигается на 1 знак влево.',
        '*0.01': 'Умножить на 0,01 — взять одну сотую числа, то есть разделить на 100: запятая сдвигается на 2 знака влево.',
        '÷0.1': 'Разделить на 0,1 — узнать, сколько десятых помещается в числе. В каждой единице 10 десятых, поэтому ответ в 10 раз больше: это то же, что умножить на 10.',
        '÷0.01': 'Разделить на 0,01 — узнать, сколько сотых помещается в числе. В каждой единице 100 сотых, поэтому ответ в 100 раз больше: это то же, что умножить на 100.' }[op];
      return { q, m, ans: N(res), sol: [why, ['', m + '=' + res]] };
    }
    if (vi === 1) {   /* + and − with different numbers of decimals (in hundredths) */
      const t = r.ri(0, 2); let a, b, m, v;
      if (t === 0) { a = r.ri(11, 399) * 10 + (r() < 0.5 ? 0 : 5); b = r.ri(11, 999); if (a % 10 === 0 && b % 10 === 0) b += 3; m = ncD(a, 2) + '+' + ncD(b, 2); v = a + b; }
      else if (t === 1) { a = r.ri(50, 300) * 10; b = r.ri(101, a - 1); if (b % 10 === 0) b += 1; m = ncD(a, 2) + '-' + ncD(b, 2); v = a - b; }
      else { a = 100 * r.pick([1, 2, 5, 10, 20]); b = r.ri(11, a - 1); if (b % 10 === 0) b += 1; m = ncD(a, 2) + '-' + ncD(b, 2); v = a - b; }
      return { q, m, ans: N(ncD(v, 2)), sol: [
        'Чтобы складывать или вычитать цифры одного разряда, запишем оба числа с двумя знаками после запятой: ' + ncTxt(dec(a, 2)) + ' и ' + ncTxt(dec(b, 2)) + '. Нули в конце дробной части число не меняют: 5 десятых — это 50 сотых.',
        ['Теперь сотые под сотыми, десятые под десятыми:', dec(a, 2) + (t === 0 ? '+' : '-') + dec(b, 2) + '=' + ncD(v, 2)]] };
    }
    if (vi === 2) {   /* multiplying decimals */
      let an, ak, bn, bk; do { ak = r.ri(1, 2); an = r.ri(2, ak === 2 ? 25 : 15); bk = r.ri(0, 1); bn = r.ri(2, 9); } while (an % 10 === 0 || (ak === 2 && an > 9 && bk === 1));
      const m = ncD(an, ak) + '*' + ncD(bn, bk), p = ncD(an * bn, ak + bk);
      return { q, m, ans: N(p), sol: [ncMulWhy(an, ak, bn, bk), ['', m + '=' + p]] };
    }
    if (vi === 3) {   /* comparing: the longest is not the largest */
      const w = r.ri(0, 9), c = r.ri(2, 8), e = r.ri(1, 9), f = r.ri(1, 9), g = r.ri(1, 9);
      const A = w * 1000 + c * 100, B = w * 1000 + (c - 1) * 100 + e * 10, C = w * 1000 + f * 10, D = w * 1000 + (c - 1) * 100 + g;   /* in thousandths: w,c · w,(c−1)e · w,0f · w,(c−1)0g */
      const neg = r() < 0.4, big = r() < 0.5, sg = neg ? -1 : 1;
      const right = neg ? (big ? -C : -A) : (big ? A : C);
      const opts = [right].concat([A, B, C, D].map(x => sg * x).filter(x => x !== right)).map(x => ncN(x, 3));
      const tx = x => ncN(sg * x, 3);
      return { q: L('Parmi les nombres suivants, lequel est le plus ' + (big ? 'grand' : 'petit') + ' ?', 'Какое из этих чисел самое ' + (big ? 'большое' : 'маленькое') + '?'), ans: ncMQ(r, opts), sol: [
        'Сравниваем по разрядам слева направо. Целые части одинаковые (' + (neg ? '−' : '') + w + '), поэтому смотрим на десятые: ' + c + ' у числа ' + tx(A) + ', ' + (c - 1) + ' у чисел ' + tx(B) + ' и ' + tx(D) + ', 0 у числа ' + tx(C) + '.',
        neg ? 'Для отрицательных чисел всё наоборот: чем дальше от нуля, тем меньше число. Дальше всех от нуля ' + tx(A) + ', ближе всех — ' + tx(C) + '. Значит, самое ' + (big ? 'большое' : 'маленькое') + ' — ' + ncN(right, 3) + '.'
          : 'Значит, самое ' + (big ? 'большое' : 'маленькое') + ' — ' + ncN(right, 3) + '.',
        'Длина записи ничего не говорит о величине: ' + ncN(A, 3) + ' = ' + ncTxt(dec(A, 3)) + ' (дописанные нули число не меняют). Сравнивают разряды слева направо, а не количество цифр.'] };
    }
    /* vi === 4: a number from its decimal parts (14 + 6/10 + 2/1000) */
    const w = r.ri(1, 99), miss = r.ri(0, 2), dg = [r.ri(1, 9), r.ri(1, 9), r.ri(1, 9)]; if (miss < 2) dg[miss] = 0; else dg[1] = 0;
    const parts = [String(w)]; dg.forEach((x, i) => { if (x) parts.push(x + '/' + Math.pow(10, i + 1)); });
    const v = w * 1000 + dg[0] * 100 + dg[1] * 10 + dg[2], ord = r() < 0.3 ? r.sh(parts) : parts, m = ord.join('+');
    const names = ['десятых', 'сотых', 'тысячных'], one = ['десятая', 'сотая', 'тысячная'], zero = dg.findIndex(x => x === 0);
    const wrong = dg.filter(x => x).join('');
    return { q: L('Donner l\'écriture décimale de ce nombre.', 'Запиши это число десятичной дробью.'), m, ans: N(ncD(v, 3), { dec: true }), sol: [
      dg.map((x, i) => x ? x + '/' + Math.pow(10, i + 1) + ' — это ' + x + ' ' + (x === 1 ? one[i] : names[i]) + ' (' + (i + 1) + '-я цифра после запятой)' : '').filter(Boolean).join('; ') + '.',
      names[zero][0].toUpperCase() + names[zero].slice(1) + ' нет, поэтому на их месте пишем 0.',
      ['', m + '=' + ncD(v, 3)],
      'Частая ошибка — ' + ncTxt(w + '.' + wrong) + ': без нуля цифра ' + dg[2] + ' попала бы в разряд сотых и означала бы ' + dg[2] + '/100, а не ' + dg[2] + '/1000.'] };
  } });

